package com.yeamin.lipi.ui

import android.content.Context
import android.graphics.Canvas
import android.graphics.ColorFilter
import android.graphics.PixelFormat
import android.graphics.drawable.Drawable
import androidx.annotation.DrawableRes
import androidx.core.content.ContextCompat

/**
 * The keyboard's icons: Material Symbols (Rounded), the Material 3 icon set, as vector
 * drawables in `res/drawable/ms_*.xml` (generated by `tools/prepare-icons.pl`; Apache 2.0,
 * see `keyboard-ui/NOTICE.txt`). The settings app uses the same files.
 */
enum class KeyboardIcon(@DrawableRes val res: Int) {
    SHIFT(R.drawable.ms_shift),
    SHIFT_ON(R.drawable.ms_shift_fill),
    CAPS_LOCK(R.drawable.ms_shift_lock_fill),
    BACKSPACE(R.drawable.ms_backspace),
    ENTER(R.drawable.ms_keyboard_return),
    GO(R.drawable.ms_arrow_forward),
    SEARCH(R.drawable.ms_search),
    SEND(R.drawable.ms_send),
    NEXT(R.drawable.ms_keyboard_tab),
    PREVIOUS(R.drawable.ms_keyboard_tab_rtl),
    DONE(R.drawable.ms_check),
    LANGUAGE(R.drawable.ms_language),
    EMOJI(R.drawable.ms_mood),
    CLIPBOARD(R.drawable.ms_content_paste),
    MIC(R.drawable.ms_mic),
    EDIT(R.drawable.ms_edit_note),
    SETTINGS(R.drawable.ms_settings),
    LOCK(R.drawable.ms_lock),
    CHEVRON_LEFT(R.drawable.ms_chevron_left),
    CHEVRON_RIGHT(R.drawable.ms_chevron_right),
    EXPAND(R.drawable.ms_open_in_full),
    DOCK(R.drawable.ms_dock_to_bottom),
    GRIP(R.drawable.ms_drag_handle),
    APPS(R.drawable.ms_grid_view),
    MIC_ON(R.drawable.ms_mic_fill),
    COLLAPSE(R.drawable.ms_expand_more),
    EXPAND_UP(R.drawable.ms_expand_less),
    SHRINK(R.drawable.ms_close_fullscreen),
    CLOSE(R.drawable.ms_close),
    GRIP_DOTS(R.drawable.ms_drag_indicator),
    ROTATE(R.drawable.ms_rotate_90_degrees_ccw),
    TRANSLATE(R.drawable.ms_translate),
    SWAP(R.drawable.ms_swap_horiz),
    DOWNLOAD(R.drawable.ms_download),
    ;

    /** A tinted copy of this icon, drawn [sizePx] square in the middle of whatever bounds it gets. */
    fun drawable(context: Context, color: Int, sizePx: Float): Drawable {
        val inner = requireNotNull(ContextCompat.getDrawable(context, res)).mutate()
        inner.setTint(color)
        return SizedIcon(inner, sizePx.toInt())
    }
}

/** Draws [inner] at a fixed size, centred in its bounds (for ImageViews and compound drawables). */
private class SizedIcon(private val inner: Drawable, private val size: Int) : Drawable() {
    override fun draw(canvas: Canvas) {
        val l = bounds.centerX() - size / 2
        val t = bounds.centerY() - size / 2
        inner.setBounds(l, t, l + size, t + size)
        inner.draw(canvas)
    }

    override fun getIntrinsicWidth() = size
    override fun getIntrinsicHeight() = size
    override fun setAlpha(alpha: Int) { inner.alpha = alpha }
    override fun setColorFilter(colorFilter: ColorFilter?) { inner.colorFilter = colorFilter }

    @Deprecated("Deprecated in Java", ReplaceWith("PixelFormat.TRANSLUCENT", "android.graphics.PixelFormat"))
    override fun getOpacity() = PixelFormat.TRANSLUCENT
}

/**
 * Icons for drawing straight onto the key canvas: one tinted drawable per icon and colour
 * role, created the first time it is drawn, so drawing allocates nothing afterwards.
 */
internal class KeyIconCache(private val context: Context, private val colors: IntArray) {
    private val cache = arrayOfNulls<Drawable>(KeyboardIcon.entries.size * colors.size)

    /** Draws [icon] in colour role [role] (an index into the colours), [size] px, centred on (cx, cy). */
    fun draw(canvas: Canvas, icon: KeyboardIcon, role: Int, cx: Float, cy: Float, size: Float) {
        val slot = icon.ordinal * colors.size + role
        val d = cache[slot] ?: requireNotNull(ContextCompat.getDrawable(context, icon.res)).mutate().also {
            it.setTint(colors[role])
            cache[slot] = it
        }
        val half = size / 2
        d.setBounds((cx - half).toInt(), (cy - half).toInt(), (cx + half).toInt(), (cy + half).toInt())
        d.draw(canvas)
    }
}
